      "path": "src/discovery.ts",
      "content": "/**\n * Ollama-native model discovery behind `llm/discoverModels`.\n *\n * The chat protocol runs on the OpenAI-compatible `/v1` surface delegated to\n * pi-ai, but the catalog lives on the native `/api` surface: `GET /api/tags`\n * lists what the endpoint serves and `POST /api/show` enriches one model with\n * its context window and capabilities. Both are anonymous on the public cloud\n * and use the configured credential when one exists, so a self-hosted or\n * gated endpoint works too.\n *\n * Two consumers read this module, and they want different shapes:\n * `discoverModels` answers a configuration surface with candidates for\n * *adoption* (so it keeps only what the endpoint described), while\n * `discoverCatalog` answers the route's own self-updating catalog with the\n * complete listing (membership comes from `/api/tags` alone). Both share one\n * decoder, so a capability the plugin serves and a capability a user may adopt\n * can never disagree.\n *\n * @module dsh-ollama-cloud/discovery\n */\n\nimport type { LlmDiscoveredModel, ModelModality } from '@deepseek-ai/dsh-llm'\n\nimport type { OllamaModelEntry } from './catalog.js'\nimport { nativeAPIBaseURL } from './config.js'\nimport { GENERIC_EFFORTS, offeredEffortMap, policyFromThinking, type ThinkingLevel } from './reasoning.js'\n\n/** Default per-request budget for one discovery call. */\nexport const DEFAULT_DISCOVERY_TIMEOUT_MS = 15000\n\n/**\n * Normalize the endpoint a configuration surface names into the native base\n * discovery talks to.\n *\n * A draft profile carries the endpoint the way a user typed it — a bare host,\n * an OpenAI-compatible `/v1` base, or the native `/api` base — so the draft is\n * run through the same normalization the plugin's own configuration uses\n * ({@link nativeAPIBaseURL}), and an absent draft falls back to the configured\n * route's base.\n *\n * @param baseURL - draft endpoint from a configuration surface, when any.\n * @param fallback - the configured route's native base.\n * @returns the native base URL to interrogate.\n */\nexport function nativeBaseFrom(baseURL: string | undefined, fallback: string): string {\n  const trimmed = baseURL?.trim() ?? ''\n  return trimmed.length === 0 ? fallback : nativeAPIBaseURL(trimmed)\n}\n\n/** Detail requests one discovery pass keeps in flight. */\nconst DETAIL_CONCURRENCY = 6\n\n/** Read one model id out of a `/api/tags` entry. */\nfunction tagModelId(entry: unknown): string | undefined {\n  if (entry === null || typeof entry !== 'object') return undefined\n  const record = entry as { name?: unknown; model?: unknown }\n  const candidate = typeof record.name === 'string' ? record.name : record.model\n  return typeof candidate === 'string' && candidate.length > 0 ? candidate : undefined\n}\n\n/**\n * Decode one `/api/tags` response into the model ids it lists.\n * @param body - parsed response body.\n * @returns de-duplicated model ids in listing order.\n */\nexport function decodeTagsResponse(body: unknown): string[] {\n  const models = (body as { models?: unknown } | null)?.models\n  if (!Array.isArray(models)) {\n    throw new Error('ollama-cloud discovery: /api/tags answered without a \"models\" array')\n  }\n  const ids: string[] = []\n  const seen = new Set<string>()\n  for (const entry of models) {\n    const id = tagModelId(entry)\n    if (id === undefined || seen.has(id)) continue\n    seen.add(id)\n    ids.push(id)\n  }\n  return ids\n}\n\n/** Read the context window out of `/api/show` `model_info` keys. */\nfunction readContextWindow(body: Record<string, unknown>): number | undefined {\n  const info = body.model_info\n  if (info === null || typeof info !== 'object') return undefined\n  for (const [key, value] of Object.entries(info as Record<string, unknown>)) {\n    if (!key.endsWith('context_length')) continue\n    if (typeof value === 'number' && Number.isFinite(value) && value > 0) return value\n  }\n  return undefined\n}\n\n/**\n * Read the capability list out of a `/api/show` body. `undefined` means the\n * endpoint said nothing, which is not the same answer as an empty list: an\n * absent vision capability is a negative capability, a missing field is\n * unknown, and adoption copies the difference into configuration.\n */\nfunction readCapabilities(body: Record<string, unknown>): string[] | undefined {\n  const capabilities = body.capabilities\n  if (!Array.isArray(capabilities)) return undefined\n  return capabilities.filter((entry): entry is string => typeof entry === 'string')\n}\n\n/**\n * Decode one `/api/show` response into a catalog entry carrying the fields\n * that endpoint discloses: context window, vision input, and thinking levels.\n *\n * Every field is either answered or left unset, and an answered field is\n * authoritative: a `capabilities` list without `thinking` is the endpoint\n * saying the model has no thinking control, which is how `reasoningEfforts:\n * false` reaches the caller. Only a *missing* field — no `capabilities` at all\n * — reads as \"the endpoint did not say\", which the catalog merge then fills\n * from what it already knew. A model that reports the thinking capability\n * without a level list gets the boolean treatment (`off` plus one `high` level)\n * because that is how Ollama answers such models: any recognized effort\n * switches thinking on.\n *\n * @param id - model id the response belongs to.\n * @param body - parsed response body.\n * @returns the entry, with unanswered fields omitted.\n */\nexport function decodeShowResponse(id: string, body: unknown): OllamaModelEntry {\n  const record = (body ?? {}) as Record<string, unknown>\n  const capabilities = readCapabilities(record)\n  const contextWindow = readContextWindow(record)\n  const policy = policyFromThinking(record.thinking)\n  // The endpoint may name the thinking capability without a ladder: the\n  // standard names apply, and no default is claimed because none was declared.\n  let efforts: Partial<Record<ThinkingLevel, string>> | false | undefined\n  if (policy !== undefined) efforts = offeredEffortMap(policy.efforts)\n  else if (capabilities === undefined) efforts = undefined\n  else efforts = capabilities.includes('thinking') ? GENERIC_EFFORTS : false\n  const defaultEffort = policy?.defaultEffort\n\n  return {\n    id,\n    ...contextWindow === undefined ? {} : { contextWindow },\n    ...capabilities === undefined ? {} : { vision: capabilities.includes('vision') },\n    ...efforts === undefined ? {} : { reasoningEfforts: efforts },\n    ...defaultEffort === undefined ? {} : { defaultEffort },\n  }\n}\n\n/**\n * Enrich one catalog entry into a discovery candidate.\n * @param entry - entry decoded from `/api/show`, when the request succeeded.\n * @param id - model id from the listing.\n * @returns the candidate metadata for adoption.\n */\nfunction toDiscoveredModel(entry: OllamaModelEntry, id: string): LlmDiscoveredModel {\n  const input: ModelModality[] | undefined = entry.vision === undefined\n    ? undefined\n    : entry.vision === true\n      ? ['text', 'image']\n      : ['text']\n  return {\n    id,\n    name: id,\n    ...entry.contextWindow === undefined ? {} : { contextWindow: entry.contextWindow },\n    ...input === undefined ? {} : { inputModalities: input },\n  }\n}\n\n/** One endpoint description discovery needs; mirrors the adapter's connection. */\nexport interface DiscoveryTarget {\n  /** Native Ollama API base, e.g. `https://ollama.com/api`. */\n  readonly baseURL: string\n  /** Credential for this pass, when one resolved. */\n  readonly apiKey?: string\n  /** Per-request budget in milliseconds. */\n  readonly requestTimeoutMs?: number\n}\n\n/** Injectable effects, so tests can drive discovery without a network. */\nexport interface DiscoveryDeps {\n  /** Fetch implementation; defaults to the global one. */\n  readonly fetch: typeof fetch\n  /** Harness attribution headers; defaults to none. */\n  readonly attribution?: () => Record<string, string>\n}\n\n/** One request attempt carrying one timeout, combined with caller cancellation. */\nfunction attemptSignal(callerSignal: AbortSignal | undefined, timeoutMs: number): AbortSignal {\n  const timeout = AbortSignal.timeout(timeoutMs)\n  return callerSignal === undefined ? timeout : AbortSignal.any([callerSignal, timeout])\n}\n\n/**\n * Statuses that mean \"this endpoint does not serve that model\" rather than\n * \"no answer yet\": Ollama answers 404 for an unknown id and 410 for a retired\n * one. Anything else (401/403/429/5xx, a timeout, a transport error) is a\n * failure to answer, which says nothing about whether the model exists.\n */\nconst MISSING_STATUSES = new Set([404, 410])\n\n/** One detail request's outcome: an answer, a refusal, or \"no answer yet\". */\ntype DetailAnswer =\n  | { readonly ok: true; readonly body: unknown }\n  | { readonly ok: false; readonly status: number }\n\n/**\n * POST one JSON call and read its reply, or report the status it refused with.\n * A transport failure or timeout still throws, because that is not an answer.\n */\nasync function postJson(\n  url: string,\n  payload: unknown,\n  headers: Record<string, string>,\n  deps: DiscoveryDeps,\n  signal: AbortSignal | undefined,\n  timeoutMs: number,\n): Promise<DetailAnswer> {\n  const response = await deps.fetch(url, {\n    method: 'POST',\n    headers: { ...headers, 'content-type': 'application/json' },\n    body: JSON.stringify(payload),\n    redirect: 'error',\n    signal: attemptSignal(signal, timeoutMs),\n  })\n  if (!response.ok) {\n    const status = response.status\n    await response.body?.cancel()\n    return { ok: false, status }\n  }\n  return { ok: true, body: await response.json() }\n}\n\n/** One model's place in the listing, and how much the endpoint said about it. */\ninterface DetailResult {\n  /** Model id from the listing. */\n  readonly id: string\n  /** Decoded `/api/show` entry, when the endpoint described the model. */\n  readonly entry?: OllamaModelEntry\n  /** The endpoint answered 404/410: it does not serve this model any more. */\n  readonly missing: boolean\n}\n\n/**\n * One endpoint listing, plus the ids its detail requests actually described.\n *\n * Membership and description are separate answers: `/api/tags` decides which\n * models exist, `/api/show` says how much is known about each. A consumer that\n * must copy metadata (adoption) filters on `described`; a consumer that serves\n * the list keeps every entry that is not retired.\n */\nexport interface DiscoveredCatalog {\n  /** Every model the listing names and the endpoint still serves, enriched where `/api/show` answered. */\n  readonly entries: readonly OllamaModelEntry[]\n  /** Ids whose `/api/show` response was decoded, in listing order. */\n  readonly described: readonly string[]\n}\n\n/**\n * List the endpoint's models and describe each with `/api/show` metadata.\n *\n * Three outcomes are kept apart, because they mean different things:\n *\n * - **described** — the endpoint answered; the entry carries its metadata.\n * - **retired** — the endpoint answered 404/410 for a model its own listing\n *   still names: it is gone, so it is left out of the catalog rather than\n *   offered and left to fail at request time.\n * - **unknown** — the detail request timed out or failed some other way. The\n *   model is kept, undeclared, and the next pass describes it; dropping a real\n *   model because one request was slow would hide it for a whole interval.\n *\n * A refused *listing* fails the whole call, so a caller reports the endpoint\n * problem instead of showing an empty catalog.\n *\n * @param target - endpoint and credential for this pass.\n * @param deps - injectable fetch and attribution headers.\n * @param signal - caller cancellation.\n * @returns the listed entries and the ids that were described.\n */\nexport async function discoverCatalog(\n  target: DiscoveryTarget,\n  deps: DiscoveryDeps,\n  signal?: AbortSignal,\n): Promise<DiscoveredCatalog> {\n  const base = target.baseURL.replace(/\\/+$/, '')\n  const timeoutMs = target.requestTimeoutMs ?? DEFAULT_DISCOVERY_TIMEOUT_MS\n  const headers: Record<string, string> = {\n    accept: 'application/json',\n    ...deps.attribution?.() ?? {},\n    ...target.apiKey === undefined ? {} : { authorization: `Bearer ${target.apiKey}` },\n  }\n\n  const listing = await deps.fetch(`${base}/tags`, {\n    headers,\n    redirect: 'error',\n    signal: attemptSignal(signal, timeoutMs),\n  })\n  if (!listing.ok) {\n    await listing.body?.cancel()\n    throw new Error(`ollama-cloud discovery: ${base}/tags answered ${listing.status}`)\n  }\n  const ids = decodeTagsResponse(await listing.json())\n\n  const entries: OllamaModelEntry[] = []\n  const described: string[] = []\n  for (let start = 0; start < ids.length; start += DETAIL_CONCURRENCY) {\n    const batch = ids.slice(start, start + DETAIL_CONCURRENCY)\n    const details: DetailResult[] = await Promise.all(\n      batch.map(async (id): Promise<DetailResult> => {\n        try {\n          const answer = await postJson(`${base}/show`, { model: id }, headers, deps, signal, timeoutMs)\n          if (!answer.ok) return { id, missing: MISSING_STATUSES.has(answer.status) }\n          return { id, entry: decodeShowResponse(id, answer.body), missing: false }\n        } catch (error) {\n          if (signal?.aborted === true) throw error\n          return { id, missing: false }\n        }\n      }),\n    )\n    for (const detail of details) {\n      if (detail.missing) continue\n      if (detail.entry === undefined) {\n        // No answer yet: the listing still says the model exists, so it is\n        // served with only what the listing said.\n        entries.push({ id: detail.id })\n        continue\n      }\n      described.push(detail.id)\n      entries.push(detail.entry)\n    }\n  }\n  return { entries, described }\n}\n\n/**\n * List the endpoint's models and describe each with `/api/show` metadata.\n *\n * Only models the endpoint describes become candidates: adoption copies the\n * context window and modalities into configuration, so a guess would be worse\n * than an omission — and a stale listing entry that answers 410 is exactly\n * what a user must not be offered. A refused listing fails the whole call, so\n * a configuration surface reports the endpoint problem instead of showing an\n * empty catalog.\n *\n * @param target - endpoint and credential for this pass.\n * @param deps - injectable fetch and attribution headers.\n * @param signal - caller cancellation.\n * @returns discovery candidates in listing order.\n */\nexport async function discoverModels(\n  target: DiscoveryTarget,\n  deps: DiscoveryDeps,\n  signal?: AbortSignal,\n): Promise<LlmDiscoveredModel[]> {\n  const catalog = await discoverCatalog(target, deps, signal)\n  const described = new Set(catalog.described)\n  return catalog.entries\n    .filter((entry) => described.has(entry.id))\n    .map((entry) => toDiscoveredModel(entry, entry.id))\n}\n"
    },
    {
      "path": "src/index.ts",
      "content": "/**\n * Ollama Cloud for DeepSeek Harness.\n *\n * One plugin instance owns the `ollama-cloud` route: chat runs through the\n * official pi-ai adapter against Ollama's OpenAI-compatible `/v1` surface,\n * model discovery reads the native `/api` surface, and the Ollama web\n * search/fetch endpoints register as `ctx.web` providers. The thinking levels\n * each model offers come from the model's own wire metadata, so the composer's\n * effort selector adjusts real capability instead of a guess.\n *\n * The catalog itself is not frozen at release: at mount — and then on an\n * interval — the plugin asks the configured endpoint what it serves and adopts\n * the answer for the running session and the next boot (see `live-catalog.ts`),\n * so a model Ollama adds, retires, or re-levels reaches users without a plugin\n * update.\n *\n * @module dsh-ollama-cloud\n */\n\nimport type { Context } from '@deepseek-ai/cordis'\n// Type-only: makes `ctx.fiber.entry` (the loader row this plugin runs as)\n// visible, which is how the plugin learns its own settings namespace.\nimport type {} from '@deepseek-ai/cordis-plugin-loader'\n// Type-only: makes `ctx.connection` (the browser session's RPC registry) visible.\nimport type {} from '@deepseek-ai/dsh-client-connection'\nimport { attributionHeaders, LlmError, type LlmDiscoveredModel, type LlmModelDiscoveryRequest } from '@deepseek-ai/dsh-llm'\n\nimport { OllamaCloudAdapter } from './adapter.js'\nimport { reportAlignment } from './alignment.js'\nimport {\n  createConnectionReader,\n  DISPLAY_NAME,\n  IDLE_REFRESH_WATCH_MS,\n  PLUGIN_NAME,\n  PROVIDER,\n  type Config as ConfigShape,\n  type ConnectionOptions,\n} from './config.js'\nimport { createCredentialResolver, type ResolveCredential } from './credentials.js'\nimport { discoverModels, nativeBaseFrom } from './discovery.js'\nimport { createLiveCatalog } from './live-catalog.js'\nimport { createUsageRpcHandler, USAGE_RPC_CHANNEL } from './rpc.js'\nimport { OllamaWebFetchProvider, OllamaWebSearchProvider } from './web.js'\n\nexport { OllamaCloudAdapter } from './adapter.js'\nexport {\n  Config,\n  createConnectionReader,\n  DEFAULT_API_KEY_ENV,\n  DEFAULT_BASE_URL,\n  DEFAULT_CONTEXT_WINDOW,\n  DEFAULT_MAX_TOKENS,\n  DEFAULT_REFRESH_MINUTES,\n  DEFAULT_STREAM_IDLE_TIMEOUT_MS,\n  DEFAULT_REQUEST_TIMEOUT_MS,\n  DISPLAY_NAME,\n  IDLE_REFRESH_WATCH_MS,\n  nativeAPIBaseURL,\n  openAICompatibleBaseURL,\n  PROVIDER,\n  resolveConnection,\n} from './config.js'\nexport { createCredentialResolver } from './credentials.js'\nexport type { ResolveCredential } from './credentials.js'\nexport type { Config as ConfigShape, ConfiguredModelEntry, ConnectionOptions, Options, ResolvedModel } from './config.js'\nexport { DEFAULT_MODELS, mergeCatalogEntry, mergeLiveCatalog } from './catalog.js'\nexport { plainOptions } from './config.js'\nexport type { CatalogSource, OllamaModelEntry } from './catalog.js'\nexport { DEFAULT_DISCOVERY_TIMEOUT_MS, discoverCatalog, discoverModels, nativeBaseFrom } from './discovery.js'\nexport type { DiscoveredCatalog, DiscoveryDeps, DiscoveryTarget } from './discovery.js'\nexport { createLiveCatalog } from './live-catalog.js'\nexport type { CachedCatalog, LiveCatalog, LiveCatalogOptions, LiveCatalogRefresh } from './live-catalog.js'\nexport {\n  CATALOG_CACHE_FILE,\n  CATALOG_CACHE_VERSION,\n  defaultCatalogCachePath,\n  readCatalogCache,\n  writeCatalogCache,\n} from './catalog-cache.js'\nexport type { CacheWriteResult, CatalogCacheSnapshot } from './catalog-cache.js'\nexport {\n  CREDENTIAL_SET_ENDPOINT,\n  CREDENTIAL_STATUS_ENDPOINT,\n  createUsageRpcHandler,\n  USAGE_ENDPOINT,\n  USAGE_RPC_CHANNEL,\n} from './rpc.js'\nexport type {\n  CredentialSetValue,\n  CredentialStatusValue,\n  UsageReadValue,\n  UsageRpcHandler,\n  WireUsageSnapshot,\n  WireUsageWindow,\n} from './rpc.js'\nexport { toWireUsage } from './rpc.js'\nexport {\n  decodeBalanceResponse,\n  readUsage,\n  USAGE_MAX_BYTES,\n  USAGE_UNSUPPORTED,\n  USAGE_WINDOW_IDS,\n  UsageError,\n} from './usage.js'\nexport type { OllamaUsageSnapshot, OllamaUsageWindow, UsageWindowId } from './usage.js'\nexport { GENERIC_EFFORTS, offeredLevels, pinEfforts, policyFromThinking } from './reasoning.js'\nexport type { ReasoningPolicy, ThinkingLevel } from './reasoning.js'\nexport { createOllamaCloudAuth, createPiAiProfile, toPiAiModel } from './profile.js'\nexport { MAX_SEARCH_RESULTS, OLLAMA_WEB_PROVIDER_ID, OllamaWebFetchProvider, OllamaWebSearchProvider } from './web.js'\n\n/** Loader row name; also the plugin's settings namespace fallback. */\nexport const name = PLUGIN_NAME\n\n/** Which pass asked for a catalog refresh; it names the log line. */\nexport type CatalogRefreshReason = 'mount' | 'interval'\n\n/** The route lives on the LLM seam. */\nexport const inject = ['llm']\n\n/**\n * What the composition's `connection` row must inject for the usage channel to\n * mount, in the order `cordis.patch.yml` restates it.\n *\n * `connection.rpc.handle()` registers the channel through the connection\n * service's own `webServer`, so the requirement sits on *that* row: a caller\n * that injects `webServer` itself still throws `cannot get property \"webServer\"\n * without inject` (reproduced against `@deepseek-ai/cordis` 4.0.5). The first\n * entry is that row's own startup dependency — the web-runtime service the\n * `0.2.1` line injects as `webStartup` (`webRuntime` before it) — restated\n * because a patch replaces the row's `inject` array wholesale.\n *\n * The list is written twice on purpose: here, so this diagnostic can name it,\n * and in the bundle patch, which is what the loader actually reads.\n * `tests/composition.test.ts` compares this constant, that patch, and the\n * installed `@deepseek-ai/dsh-web-app` composition, so the next upstream move\n * fails `pnpm test` instead of a user's boot.\n */\nexport const USAGE_CHANNEL_ROW_INJECT = ['webStartup', 'webServer'] as const\n\n/** Default settings namespace when the loader does not supply an entry id. */\nexport const DEFAULT_SETTINGS_NAMESPACE = PLUGIN_NAME\n\n/**\n * Build the credential resolution a chat request needs.\n *\n * A route that names a reference fails loud when it is unset — handing pi-ai\n * `undefined` would let it pick up an unrelated ambient key and bill another\n * tenant — while a route that names none (a local Ollama server) sends no\n * auth at all.\n *\n * @param resolveCredential - the per-request seam resolver.\n * @returns the route's key resolver.\n */\nexport function createRouteApiKeyResolver(\n  resolveCredential: ResolveCredential,\n): (facts: ConnectionOptions) => Promise<string | undefined> {\n  return async (facts) => {\n    const reference = facts.apiKeyEnv\n    if (reference === undefined) return undefined\n    const key = await resolveCredential(reference)\n    if (key !== undefined) return key\n    throw new LlmError(\n      `llm-ollama-cloud: no API key for provider route \"${PROVIDER}\";`\n      + ` its configuration resolves \"${reference}\", which is not set —`\n      + ' store it through the credentials service (the Models page or plugin settings) or export it,'\n      + ' and clear the reference only if the endpoint authenticates on its own',\n      'MISSING_CREDENTIAL',\n    )\n  }\n}\n\n/**\n * Mount the Ollama Cloud route, its discovery surface, its web providers, and\n * the catalog refresh that keeps the route's model list current.\n * @param ctx - the plugin's context.\n * @param config - live configuration for this row.\n */\nexport function apply(ctx: Context, config: ConfigShape): void {\n  const catalog = createLiveCatalog({\n    deps: { fetch, attribution: attributionHeaders },\n  })\n  const connection = createConnectionReader(config, (error) => {\n    ctx.logger.warn('llm-ollama-cloud: configuration is invalid; keeping the last good connection facts')\n    ctx.logger.warn(error)\n  }, catalog)\n  // Resolve once at mount so an unusable row config fails loudly instead of\n  // surfacing as a request-time error nobody attributes to configuration.\n  connection()\n\n  // The route streams through this package's own pi-ai while the harness that\n  // drives it belongs to the app, so the two can drift across app releases.\n  // Say so in the log at mount instead of letting the drift surface later as a\n  // cryptic request failure (the 0.2.0 incident, ADR 0004).\n  reportAlignment(ctx.logger)\n\n  const settingsNs = ctx.fiber.entry?.options.id ?? DEFAULT_SETTINGS_NAMESPACE\n  const resolveCredential = createCredentialResolver(ctx, name)\n\n  /** The configured key, or `undefined` when nothing usable is set. */\n  const storedKey = async (facts: ConnectionOptions): Promise<string | undefined> => {\n    const reference = facts.apiKeyEnv\n    return reference === undefined ? undefined : resolveCredential(reference)\n  }\n\n  /**\n   * Ask the configured endpoint what it serves and adopt the answer.\n   *\n   * Ollama adds and retires cloud models on its own schedule, so this — not the\n   * shipped snapshot — is what keeps the model list and every model's thinking\n   * levels current. Nothing here is fatal: a failure leaves the catalog in use\n   * exactly as it was, and the next pass (or the next boot) tries again.\n   */\n  let refreshing = false\n  const refreshCatalog = async (reason: CatalogRefreshReason): Promise<void> => {\n    if (refreshing) return\n    refreshing = true\n    try {\n      const facts = connection()\n      const apiKey = await storedKey(facts)\n      const result = await catalog.refresh({\n        baseURL: facts.nativeBaseURL,\n        ...apiKey === undefined ? {} : { apiKey },\n        requestTimeoutMs: facts.requestTimeoutMs,\n      })\n      const unpersisted = result.cache.ok ? '' : `; cache not written (${result.cache.error})`\n      ctx.logger.info(\n        `llm-ollama-cloud: ${reason} catalog refresh: ${result.models} models,`\n        + ` ${result.described} described by /api/show,`\n        + ` ${result.changed ? 'catalog changed' : 'catalog unchanged'}${unpersisted}`,\n      )\n    } catch (error) {\n      ctx.logger.warn(\n        `llm-ollama-cloud: ${reason} catalog refresh failed;`\n        + ' the catalog already in use keeps serving (the next pass retries)',\n      )\n      ctx.logger.warn(error)\n    } finally {\n      refreshing = false\n    }\n  }\n\n  const resolveApiKey = createRouteApiKeyResolver(resolveCredential)\n\n  const adapter = new OllamaCloudAdapter({\n    options: connection,\n    resolveApiKey,\n    resolveAttachments: () => ctx.get('attachments'),\n  })\n\n  ctx.llm.registerConfigurableProviders([{\n    provider: PROVIDER,\n    displayName: DISPLAY_NAME,\n    settingsNs,\n    settingsPath: [],\n  }])\n  ctx.llm.registerAdapter([PROVIDER], adapter)\n\n  /**\n   * Interrogate one endpoint for its model catalog. A configuration surface\n   * may pass the draft endpoint and a one-shot key; otherwise the configured\n   * route's endpoint and stored credential answer, and the public cloud\n   * metadata endpoints need no credential at all.\n   */\n  ctx.llm.registerModelDiscovery(settingsNs, async (request: LlmModelDiscoveryRequest, signal) => {\n    const facts = connection()\n    const baseURL = nativeBaseFrom(request.baseURL, facts.nativeBaseURL)\n    const apiKey = request.apiKey ?? await storedKey(facts)\n    const discovered: readonly LlmDiscoveredModel[] = await discoverModels(\n      {\n        baseURL,\n        ...apiKey === undefined ? {} : { apiKey },\n        requestTimeoutMs: facts.requestTimeoutMs,\n      },\n      { fetch, attribution: attributionHeaders },\n      signal,\n    )\n    return discovered\n  })\n\n  // Optional surface: a headless composition has no browser session, so the\n  // usage channel simply never mounts there and everything else keeps working.\n  ctx.inject(['connection'], (connectionCtx) => {\n    const handler = createUsageRpcHandler({\n      connection,\n      resolveCredential,\n      credentials: () => ctx.get('credentials'),\n      fetch,\n      attribution: attributionHeaders,\n    })\n    connectionCtx.effect(() => {\n      try {\n        return connectionCtx.connection.rpc.handle(USAGE_RPC_CHANNEL, handler)\n      } catch (error) {\n        // Loud instead of silent: the browser card then reports a restart hint,\n        // and this line names the composition change that fixes it.\n        ctx.logger.warn(\n          'llm-ollama-cloud: the usage channel could not mount on the connection service;'\n          + ` the connection row must inject ${USAGE_CHANNEL_ROW_INJECT.join(' + ')}`\n          + ' (this bundle patch restates that list — re-check it against the composition'\n          + ' after a harness upgrade)',\n        )\n        ctx.logger.warn(error)\n        return () => {}\n      }\n    }, 'llm-ollama-cloud: usage RPC channel')\n  })\n\n  // Optional capability: a headless composition without the web seam simply\n  // has no search/fetch to offer, and everything else keeps working.\n  ctx.inject(['web'], (webCtx) => {\n    const options = {\n      baseURL: () => connection().nativeBaseURL,\n      resolveApiKey: () => storedKey(connection()),\n      requestTimeoutMs: () => connection().requestTimeoutMs,\n    }\n    webCtx.effect(() => {\n      const disposeSearch = webCtx.web.registerSearchProvider(new OllamaWebSearchProvider(options))\n      const disposeFetch = webCtx.web.registerFetchProvider(new OllamaWebFetchProvider(options))\n      return () => {\n        disposeFetch()\n        disposeSearch()\n      }\n    }, 'llm-ollama-cloud: web providers')\n  })\n\n  // Say which catalog this session starts from. The cache is what makes the\n  // first model list already the endpoint's last answer, so a failure to reach\n  // the endpoint at mount is a delay, not a regression.\n  const cached = catalog.cached()\n  ctx.logger.info(\n    cached === undefined\n      ? 'llm-ollama-cloud: no cached catalog yet; serving the shipped snapshot until the endpoint answers'\n      : `llm-ollama-cloud: serving the cached catalog of ${cached.endpoint}`\n        + ` (${cached.models} models, fetched ${new Date(cached.fetchedAt).toISOString()})`,\n  )\n\n  if (config.autoRefresh.get()) {\n    // Deliberately not awaited: a slow endpoint must not hold up the boot, and\n    // the model list is already correct from the cache (or the snapshot).\n    void refreshCatalog('mount')\n  }\n\n  // The scheduler re-reads the live configuration twice per pass — once to\n  // decide how long to wait, once when the timer fires to decide what that\n  // pass does — so a change never has to survive a whole interval, and\n  // switching the refresh off takes effect at the next tick instead of\n  // requiring a reload. While it is off (or mount-only) the chain keeps\n  // ticking on the idle cadence without touching the network, which is what\n  // makes switching it back on work the same way.\n  ctx.effect(() => {\n    let stopped = false\n    let timer: ReturnType<typeof setTimeout> | undefined\n    /** Minutes to schedule: `0` means this pass must not fetch. */\n    const intervalMinutes = (): number => (config.autoRefresh.get() ? config.refreshMinutes.get() : 0)\n    const arm = (): void => {\n      if (stopped) return\n      const scheduled = intervalMinutes()\n      timer = setTimeout(() => {\n        if (intervalMinutes() > 0) void refreshCatalog('interval')\n        arm()\n      }, scheduled > 0 ? scheduled * 60_000 : IDLE_REFRESH_WATCH_MS)\n      timer.unref?.()\n    }\n    arm()\n    return () => {\n      stopped = true\n      if (timer !== undefined) clearTimeout(timer)\n    }\n  }, 'llm-ollama-cloud: catalog refresh timer')\n}\n"
